 final Handler timer=new Handler();FrameLayout root;TextureView texture;ImageView image;TextView center,title,status,pause;LinearLayout controls;SeekBar seek;Surface output;CastService connected;Bitmap showing;boolean foreground=false,tracking=false,holding=false,revealingGesture=false,presented=false;int shownGeneration=-1;long controlsUntil=0;
 int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
 TextView label(String text,int size){TextView view=new TextView(this);view.setText(text);view.setTextColor(Color.WHITE);view.setTextSize(size);view.setPadding(dp(12),dp(8),dp(12),dp(8));return view;}
 @Override public void onCreate(Bundle state){super.onCreate(state);root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);texture=new TextureView(this);texture.setSurfaceTextureListener(this);root.addView(texture,new FrameLayout.LayoutParams(-1,-1));image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setVisibility(View.GONE);root.addView(image,new FrameLayout.LayoutParams(-1,-1));center=label("Waiting for cast",24);center.setGravity(Gravity.CENTER);root.addView(center,new FrameLayout.LayoutParams(-1,-1));controls=new LinearLayout(this);controls.setOrientation(1);controls.setBackgroundColor(0xd9000000);title=label("Cast",20);controls.addView(title);status=label("",14);controls.addView(status);seek=new SeekBar(this);controls.addView(seek);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&connected!=null)connected.seek(value);}public void onStartTrackingTouch(SeekBar bar){tracking=true;timer.removeCallbacks(hide);}public void onStopTrackingTouch(SeekBar bar){tracking=false;revealControls();}});HorizontalScrollView strip=new HorizontalScrollView(this);LinearLayout buttons=new LinearLayout(this);strip.addView(buttons);controls.addView(strip,new LinearLayout.LayoutParams(-1,dp(52)));button(buttons,"Back",()->leave());pause=button(buttons,"Pause",()->{if(connected!=null&&connected.active!=null)connected.local(connected.active.wantPlay?"Pause":"Play");});button(buttons,"Stop",()->{if(connected!=null)connected.local("Stop");leave();});button(buttons,"Compatibility",()->new AlertDialog.Builder(this).setTitle("Video compatibility").setMessage("MP4 is a container, not a codec guarantee. Decoder support depends on this device, video codec/profile, resolution and stream. If audio plays but video does not, try sender-side transcoding to H.264 Baseline with AAC audio, 8-bit yuv420p, and a modest resolution. No extra decoder or transcoder is bundled.").setPositiveButton("OK",(dialog,which)->revealControls()).show());root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));controls.setVisibility(View.GONE);setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);immersivePlayer();}
