 void immersivePlayer(){getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);int flags=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;if(Build.VERSION.SDK_INT>=19)flags|=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;getWindow().getDecorView().setSystemUiVisibility(flags);}
 final Runnable hide=new Runnable(){public void run(){long remaining=controlsUntil-SystemClock.uptimeMillis();if(tracking||holding){timer.postDelayed(this,250);return;}if(remaining>0){timer.postDelayed(this,remaining);return;}if(connected==null||!connected.failed)controls.setVisibility(View.GONE);}};
