 void fit(){if(connected==null||connected.videoWidth<=0||connected.videoHeight<=0||texture.getWidth()==0||texture.getHeight()==0)return;float w=texture.getWidth(),h=texture.getHeight(),scale=Math.min(w/connected.videoWidth,h/connected.videoHeight);Matrix transform=new Matrix();transform.setScale(connected.videoWidth*scale/w,connected.videoHeight*scale/h,w/2,h/2);texture.setTransform(transform);}
 final Runnable update=new Runnable(){public void run(){if(!foreground)return;CastService service=CastService.instance;if(service!=connected){if(connected!=null&&output!=null)connected.detachSurface(output);connected=service;shownGeneration=-1;}if(service==null){center.setVisibility(View.VISIBLE);center.setText("Receiver stopped");status.setText("Background receiving is unavailable or disabled");controls.setVisibility(View.VISIBLE);}else{if(output!=null)service.attachSurface(output);if(service.generation!=shownGeneration){shownGeneration=service.generation;service.dismissedGeneration=-1;if(!tracking&&!holding&&SystemClock.uptimeMillis()>=controlsUntil)controls.setVisibility(View.GONE);}title.setText(service.title);status.setText(service.detail+(service.hasVideo?" / "+service.videoWidth+"x"+service.videoHeight:""));pause.setText(service.active!=null&&service.active.wantPlay?"Pause":"Play");if(!tracking&&service.active!=null){seek.setMax((int)Math.min(Integer.MAX_VALUE,Math.max(1,service.active.duration)));seek.setProgress((int)Math.min(Integer.MAX_VALUE,service.active.position));}if(service.photo!=null&&showing!=service.photo){showing=service.photo;image.setImageBitmap(showing);}boolean retainPhoto=showing!=null&&(service.photoMode||(!service.videoRendered&&(!service.prepared||service.hasVideo)));image.setVisibility(retainPhoto?View.VISIBLE:View.GONE);texture.setVisibility(service.photoMode?View.INVISIBLE:View.VISIBLE);fit();if(service.failed){center.setVisibility(View.VISIBLE);center.setText(service.detail+"\n\nUse Compatibility for format guidance.");controls.setVisibility(View.VISIBLE);}else if(service.photoMode){if(service.photo!=null)presented=true;center.setVisibility(presented?View.GONE:View.VISIBLE);center.setText("Loading image");}else if(service.videoRendered){presented=true;center.setVisibility(View.GONE);}else if(service.prepared&&!service.hasVideo){presented=true;center.setVisibility(View.VISIBLE);center.setText("Audio playback\n"+service.title);}else{center.setVisibility(presented?View.GONE:View.VISIBLE);center.setText(!service.prepared?"Preparing cast":SystemClock.elapsedRealtime()-service.preparedAt>8000?"No video frame yet\nCheck codec compatibility":"Starting video");}}timer.postDelayed(this,300);}};
 void leave(){if(connected!=null)connected.dismissedGeneration=connected.generation;finish();}
 @Override public void onBackPressed(){leave();}
 @Override protected void onResume(){super.onResume();foreground=true;CastService.visible=new WeakReference<CastService.Presenter>(this);if(texture.isAvailable()&&output==null)connect(texture.getSurfaceTexture());timer.post(update);if(SystemClock.uptimeMillis()>=controlsUntil)controls.setVisibility(View.GONE);else timer.postDelayed(hide,controlsUntil-SystemClock.uptimeMillis());immersivePlayer();}
